using Mbb.Archive.Modules.Archive.Application;
using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;using Mbb.Archive.BuildingBlocks.Application;using Mbb.Archive.Modules.Archive.Application.Abstractions;using Mbb.Archive.Modules.Archive.Application.Records.Declare;using Mbb.Archive.Modules.Archive.Application.Records.Get;using Mbb.Archive.Modules.Archive.Application.Records.List;using Mbb.Archive.Modules.Archive.Application.Records.RegisterCandidate;using Mbb.Archive.Modules.Archive.Infrastructure.Messaging;using Mbb.Archive.Modules.Archive.Infrastructure.Persistence;
namespace Mbb.Archive.Modules.Archive.Infrastructure;
public static class ArchiveModule{public static IServiceCollection AddArchiveModule(this IServiceCollection services,IConfiguration config){var cs=config.GetConnectionString("Archive");if(string.IsNullOrWhiteSpace(cs))throw new InvalidOperationException("Connection string 'Archive' is not configured.");services.AddDbContext<ArchiveDbContext>(o=>o.UseNpgsql(cs));services.AddSingleton(TimeProvider.System);services.AddScoped<EfArchiveRepository>();services.AddScoped<IArchiveRecordRepository>(sp=>sp.GetRequiredService<EfArchiveRepository>());services.AddScoped<IArchiveQueries>(sp=>sp.GetRequiredService<EfArchiveRepository>());services.AddScoped<IUnitOfWork<ArchiveBoundary>>(sp=>sp.GetRequiredService<ArchiveDbContext>());services.AddScoped<IInbox<ArchiveBoundary>>(sp=>sp.GetRequiredService<ArchiveDbContext>());services.AddScoped<IOutbox<ArchiveBoundary>>(sp=>sp.GetRequiredService<ArchiveDbContext>());services.AddScoped<RegisterArchiveCandidateCommandHandler>();services.AddScoped<DeclareArchiveRecordCommandHandler>();services.AddScoped<GetArchiveRecordQueryHandler>();services.AddScoped<GetArchiveRecordsQueryHandler>();services.AddHostedService<OriginalStoredArchiveConsumer>();services.AddHostedService<ArchiveOutboxPublisher>();return services;}}
